READ-ONLY SQL vs public.grok_drive_index (cols title,layer,url,content,fts — schema 010_grok_drive_index.sql). No secrets.
SELECT title, layer, url, left(content, 180) AS snippet, ts_rank(fts, websearch_to_tsquery('english', 'HOW-TO-READ-INDEX')) AS rank FROM public.grok_drive_index WHERE fts @@ websearch_to_tsquery('english', 'HOW-TO-READ-INDEX') ORDER BY rank DESC LIMIT 8;
Alt: SELECT title, layer, url, left(content, 180) AS snippet, rank FROM public.search_grok_drive('share_log', 8);
